const trig=$('Entrada desde 01').item.json;
const cfg=$('CONFIGURACIÓN - EDITAR').item.json._cfg;
const chatId=String(trig.message?.chat?.id??'');
const text=(trig.message?.text??'').trim();
const now=Date.now();
function ms(v){const d=new Date(v);return isNaN(d)?0:d.getTime();}
const rows=items.map(i=>i.json).filter(r=>
  String(r['Chat ID']??'')===chatId &&
  String(r.Estado||'').toUpperCase()==='PENDIENTE' &&
  ['CORRECCION_SELECCION','CORRECCION_CONFIRMAR'].includes(String(r['Intención']||'')) &&
  (!r.Expira || ms(r.Expira)>now)
).sort((a,b)=>ms(b['Fecha/Hora'])-ms(a['Fecha/Hora']));
const row=rows[0]||null;
let ctx=null;
if(row){try{ctx=JSON.parse(row['Datos parciales JSON']||'null');}catch(e){}}
return [{json:{
