const cfg = {
  spreadsheet_id: 'YOUR_GOOGLE_SHEET_ID',
  telegram_id_titular_a: 111111111, // reemplazar
  telegram_id_titular_b: 222222222,
  timezone: 'America/Argentina/Buenos_Aires',
  confidence_threshold: 0.95,
  openai_model: 'gpt-5.6-luna'
};
return items.map(item => ({json: {...item.json, _cfg: cfg}}));

const trig=$('Entrada desde 01').item.json;
const cfg=$('CONFIGURACIÓN - EDITAR').item.json._cfg;
const chatId=String(trig.message?.chat?.id??'');
const text=(trig.message?.text??'').trim();
const now=Date.now();
function ms(v){const d=new Date(v);return isNaN(d)?0:d.getTime();}
const candidates=items.map(i=>i.json).filter(r=>
  String(r['Chat ID']??'')===chatId &&
  String(r.Estado||'').toUpperCase()==='PENDIENTE' &&
  ['REVISION_IMPORTACION','CONFIRMAR_IMPORTACION'].includes(String(r['Intención']||'')) &&
  (!r.Expira || ms(r.Expira)>now)
).sort((a,b)=>ms(b['Fecha/Hora'])-ms(a['Fecha/Hora']));
const row=candidates[0]||null;
