}}];

const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};

function requiredMissing(p) {
  if (p.intent === 'vencimiento') {
    if (!p.fecha) return 'fecha';
    if (!p.monto_ars) return 'monto';
    if (!p.concepto_vencimiento) return 'concepto';
  }
  if (p.intent === 'saldo_inversion') {
    if (!p.inversion) return 'inversion';
    if (!p.fecha) return 'fecha';
    if (!p.monto_ars) return 'monto';
  }
  if (p.intent === 'movimiento') {
    if (!p.clase) return 'clase';
    if (!p.fecha) return 'fecha';
    const cur=String(p.moneda_original||'ARS').toUpperCase();
    if (cur==='USD') {
      if (p.monto_original===null || p.monto_original===undefined || p.monto_original==='') return 'monto';
    } else if (!p.monto_ars) return 'monto';
    if (p.clase === 'Egreso' && !p.cuenta_origen) return 'cuenta_origen';
    if (p.clase === 'Ingreso' && !p.cuenta_destino) return 'cuenta_destino';
    if (p.clase === 'Transferencia' && (!p.cuenta_origen || !p.cuenta_destino)) return 'cuentas_transferencia';
    if (p.clase === 'Ajuste patrimonial' && (!p.cuenta_origen && !p.cuenta_destino)) return 'cuenta_ajuste';
    if (p.clase === 'Egreso' && !p.categoria) return 'categoria';
  }
  return null;
}

function questionFor(miss, p) {
  return p.pregunta || (
    miss === 'cuenta_origen' ? '¿Desde qué cuenta se pagó?' :
    miss === 'cuenta_destino' ? '¿En qué cuenta ingresó?' :
    miss === 'cuentas_transferencia' ? '¿Desde qué cuenta y hacia cuál fue la transferencia?' :
    miss === 'cuenta_ajuste' ? '¿Qué cuenta afecta el ajuste patrimonial?' :
    miss === 'categoria' ? '¿A qué categoría corresponde?' :
    miss === 'fecha' ? '¿Qué fecha corresponde?' :
    miss === 'monto' ? '¿Cuál es el importe?' :
    'Necesito un dato más para registrarlo con seguridad. ¿Podés aclarármelo?'
  );
}

return items.map((item, idx) => {
  const x = item.json;
  const cfg = x._cfg;
  const p = {...(x.interpretation || {})};
  const key = String(x.chat_id);

  // Todo Ingreso/Egreso manual por Telegram se registra en efectivo de su moneda.
  if (p.intent === 'movimiento' && p.clase === 'Egreso') {
    p.cuenta_origen = String(p.moneda_original||'ARS').toUpperCase()==='USD' ? 'Efectivo USD' : 'Efectivo';
  }
  if (p.intent === 'movimiento' && p.clase === 'Ingreso') {
    p.cuenta_destino = String(p.moneda_original||'ARS').toUpperCase()==='USD' ? 'Efectivo USD' : 'Efectivo';
  }

  const miss = requiredMissing(p);
  const ask = p.intent === 'correccion' ? false : Boolean(
    p.ambiguo ||
    Number(p.confidence ?? 0) < Number(cfg.confidence_threshold) ||
    miss
  );

  if (ask) {
    const question = questionFor(miss, p);
    // Un lote válido no debería llegar acá. Si llega uno inválido, no se guarda parcialmente.
    if (!x.batch_count || Number(x.batch_count) <= 1) {
      store.pending[key] = {
        created_at: new Date().toISOString(),
        original_text: x.pending_context?.original_text || x.text,
        last_text: x.text,
        interpretation: p,
        missing_field: p.missing_field || miss,
        question
      };
    }
    return {
      json: {...x, action:'ask', question, interpretation:p},
      binary: item.binary,
      pairedItem: {item: idx}
    };
  }

  delete store.pending[key];

  const action = (
    p.intent === 'consulta' ||
    p.intent === 'correccion' ||
    p.intent === 'desconocido'
  ) ? 'other' : 'save';

  return {
    json: {...x, action, interpretation:p},
    binary: item.binary,
    pairedItem: {item: idx}
  };
});

const msg = $json.message ?? {};
const cfg = $json._cfg;

const chatId = msg.chat?.id ?? null;
const userId = msg.from?.id ?? null;
const text = (msg.text ?? msg.caption ?? '').trim();
const messageId = msg.message_id ?? null;

let persona = 'Sin identificar';
if (Number(userId) === Number(cfg.telegram_id_titular_a) && Number(cfg.telegram_id_titular_a) !== 0) persona = 'Titular A';
if (Number(userId) === Number(cfg.telegram_id_titular_b) && Number(cfg.telegram_id_titular_b) !== 0) persona = 'Titular B';

const norm = (s) => s
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/\s+/g,' ').trim();

const t = norm(text);
const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};
const pending = store.pending[String(chatId)] || null;

function parseMoney(raw) {
  if (!raw) return null;
  let s = String(raw).replace(/[^\d.,-]/g,'').trim();
  if (!s) return null;
  // Argentina: 120.000,50 / 120000 / 120,50
  const hasComma = s.includes(',');
  const hasDot = s.includes('.');
  if (hasComma && hasDot) s = s.replace(/\./g,'').replace(',','.');
  else if (hasComma) s = s.replace(',','.');
  else if (hasDot && /^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g,'');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function extractAmount(original) {
  const peso = original.match(/\$\s*([\d.]+(?:,\d{1,2})?)/);
  if (peso) return parseMoney(peso[1]);
  const candidates = [...original.matchAll(/(?<!\d)(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d{4,}(?:,\d{1,2})?)(?!\d)/g)]
    .map(m => parseMoney(m[1])).filter(n => n !== null);
  return candidates.length ? candidates[candidates.length - 1] : null;
}

const months = {
  enero:1,febrero:2,marzo:3,abril:4,mayo:5,junio:6,julio:7,agosto:8,
  septiembre:9,setiembre:9,octubre:10,noviembre:11,diciembre:12
};

function todayParts() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: cfg.timezone, year:'numeric', month:'2-digit', day:'2-digit'
  }).formatToParts(new Date());
  const get = k => Number(parts.find(p => p.type === k)?.value);
  return {y:get('year'),m:get('month'),d:get('day')};
}

function iso(y,m,d) {
  return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}

function extractDate(s) {
  const now = todayParts();
  let m = s.match(/\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/);
  if (m) {
    let y = m[3] ? Number(m[3]) : now.y;
    if (y < 100) y += 2000;
    return iso(y, Number(m[2]), Number(m[1]));
  }
  m = norm(s).match(/\b(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+de\s+(\d{4}))?\b/);
  if (m) return iso(m[3] ? Number(m[3]) : now.y, months[m[2]], Number(m[1]));
  if (/\bhoy\b/.test(norm(s))) return iso(now.y,now.m,now.d);
  if (/\bayer\b/.test(norm(s))) {
    const d=new Date(Date.UTC(now.y,now.m-1,now.d)); d.setUTCDate(d.getUTCDate()-1);
    return iso(d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate());
  }
  if (/\banteayer\b/.test(norm(s))) {
    const d=new Date(Date.UTC(now.y,now.m-1,now.d)); d.setUTCDate(d.getUTCDate()-2);
    return iso(d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate());
  }
  return null;
}

function cleanConceptVencimiento(original) {
  const x = original
    .replace(/^.*?\bvence\b/i,'')
    .replace(/\bpor\b\s*\$?\s*[\d.,]+.*$/i,'')
    .trim()
    .replace(/^(la|el|los|las)\s+/i,'');
  return x || null;
}


function manualCategory(s) {
  // Solo asociaciones suficientemente explícitas para no gastar IA innecesariamente.
  if (/\bcositas de casa\b/.test(s)) return 'Cositas de Casa';
  if (/\bgastos financieros\b/.test(s)) return 'Gastos financieros';
  if (/\bgastos varios\b/.test(s)) return 'Gastos varios';
  if (/\bcomida\b/.test(s)) return 'Comida';
  if (/\bsalud\b/.test(s)) return 'Salud';
  if (/\beducacion\b/.test(s)) return 'Educación';
  if (/\bocio\b/.test(s)) return 'Ocio';
  if (/\bimpuestos?\b/.test(s)) return 'Impuestos';
  if (/\b(?:vehiculos?|suran)\b/.test(s)) return 'Vehículos';
  // Fiesta y Suran quedan como alias históricos de la categoría unificada Vehículos.
  if (/\b(?:para\s+el|del|al|ford|auto)\s+fiesta\b/.test(s)) return 'Vehículos';
  if (/\b(?:nafta|combustible|gasoil|gnc|patente|peaje|estacionamiento|taller|mecanico|mecanica|service|aceite|cubiertas?|repuestos?|lavado)\b/.test(s)) return 'Vehículos';
  // "Casa" puede ser ubicación; auto solo si la frase apunta al hogar como destino del gasto.
  if (/\b(?:para\s+la|de\s+la)\s+casa\b/.test(s)) return 'Casa';
  return null;
}


function parseCompactExpense(original) {
  // Carga rápida flexible ARS/USD.
  // Ejemplos:
  //   comida 3000
  //   salud 2000 USD
  //   salud 2000 USD cot 1510
  // La cotización manual, si está informada, tiene prioridad en reportes.
  const raw = String(original ?? '').trim();
  const s = norm(raw);

  const words = s.split(/\s+/).filter(Boolean);
  if (words.length > 12) return null;
  if (/[?¿]/.test(raw)) return null;

  const usdRx = /(?:\bUSD\b|U\$S|US\$|\bD[ÓO]LARES?\b)/i;
  const isUSD = usdRx.test(raw);

  // Separar fecha y cotización para no confundirlas con el importe.
  const cotMatch = raw.match(/\b(?:cot|cotiz(?:acion|ación)?)\.?\s*[:=]?\s*\$?\s*(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?)/i);
  const cot = cotMatch ? parseMoney(cotMatch[1]) : null;

  let amountScope = raw;
  if (cotMatch) amountScope = amountScope.replace(cotMatch[0], ' ');
  amountScope = amountScope
    .replace(/\b\d{1,2}[\/-]\d{1,2}(?:[\/-]\d{2,4})?\b/g, ' ')
    .replace(usdRx, ' ');

  const moneyMatches = [...amountScope.matchAll(/(?:ARS\s*)?\$?\s*(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?)/gi)];
  if (moneyMatches.length !== 1) return null;

  const amount = parseMoney(moneyMatches[0][1]);
  if (amount === null) return null;

  let category = null;
  if (/\bcositas de casa\b/.test(s)) category='Cositas de Casa';
  else if (/\bgastos? financieros?\b/.test(s)) category='Gastos financieros';
  else if (/\bgastos? varios\b/.test(s)) category='Gastos varios';
  else if (/\bcomida\b|\balimentacion\b/.test(s)) category='Comida';
  else if (/\bsalud\b/.test(s)) category='Salud';
  else if (/\beducacion\b/.test(s)) category='Educación';
  else if (/\bocio\b/.test(s)) category='Ocio';
  else if (/\bimpuestos?\b/.test(s)) category='Impuestos';
  else if (/\b(?:vehiculos?|suran)\b/.test(s)) category='Vehículos';
  else if (/\b(?:nafta|combustible|gasoil|gnc|patente|peaje|estacionamiento|taller|mecanico|mecanica|service|aceite|cubiertas?|repuestos?|lavado)\b/.test(s)) category='Vehículos';
  else if (/\bfiesta\b/.test(s) &&
      /\b(auto|ford|nafta|combustible|gasoil|gas|seguro|patente|peaje|estacionamiento|taller|mecanico|mecanica|service|aceite|cubierta|repuesto|lavado)\b/.test(s)) {
    category='Vehículos';
  } else if (/\bcasa\b/.test(s) &&
      /\b(hogar|arreglo|reparacion|mueble|limpieza|pintura|ferreteria|materiales|expensas|alquiler)\b/.test(s)) {
    category='Casa';
  }

  // Formas mínimas exactas.
  let withoutMoney = raw;
  if (cotMatch) withoutMoney = withoutMoney.replace(cotMatch[0], ' ');
  withoutMoney = withoutMoney
    .replace(/\b\d{1,2}[\/-]\d{1,2}(?:[\/-]\d{2,4})?\b/g, ' ')
    .replace(usdRx, ' ')
    .replace(moneyMatches[0][0], ' ');
  withoutMoney = norm(withoutMoney);

  if (!category && ['fiesta','suran','vehiculo','vehiculos'].includes(withoutMoney)) category='Vehículos';
  if (!category && withoutMoney === 'casa') category='Casa';
  if (!category) return null;

  return {
    amount,
    category,
    currency: isUSD ? 'USD' : 'ARS',
    cot: isUSD && cot && cot > 0 ? cot : null
  };
}

// Carga múltiple de gastos en un solo mensaje.
// Formato recomendado: una línea por gasto (también acepta ; como separador).
// Ejemplo:
// comida 3500 pan
// salud 8200 farmacia
// nafta 15000
const batchLines = String(text || '')
  .split(/\r?\n|;/)
  .map(s => s.trim())
  .filter(Boolean);

if (!pending && batchLines.length >= 2 && batchLines.length <= 20) {
  const parsedBatch = batchLines.map((line, idx) => {
    const c = parseCompactExpense(line);
    if (!c) return null;
    return {
      line,
      idx,
      amount: c.amount,
      category: c.category,
      currency: c.currency || 'ARS',
      cot: c.cot || null,
      date: extractDate(line) || iso(todayParts().y,todayParts().m,todayParts().d)
    };
  });

  if (parsedBatch.every(Boolean)) {
    return parsedBatch.map((b, idx) => ({
      json: {
        _cfg: cfg,
        chat_id: chatId,
        telegram_user_id: userId,
        telegram_message_id: messageId,
        persona,
        text: b.line,
        pending_context: null,
        batch_index: idx,
        batch_count: parsedBatch.length,
        batch_source_text: text,
        quick: {
          intent: 'movimiento',
          clase: 'Egreso',
          subtipo: 'Compra',
          monto_ars: b.currency === 'USD' ? (b.cot ? b.amount * b.cot : null) : b.amount,
          moneda_original: b.currency,
          monto_original: b.amount,
          cotizacion_ars: b.cot,
          fuente_cotizacion: b.cot ? 'OPERACIÓN REAL MANUAL' : null,
          cuenta_origen: b.currency === 'USD' ? 'Efectivo USD' : 'Efectivo',
          cuenta_destino: null,
          categoria: b.category,
          detalle: b.line,
          fecha: b.date,
          inversion: null,
          concepto_vencimiento: null,
          frecuencia: null,
          query_type: null,
          query_category: null,
          query_categories: [],
          query_period: null,
          query_periods: [],
          query_month: null,
          query_year: null,
          query_days: null,
          query_only_cards: false,
          query_investment: null,
          confidence: 0.99,
          ambiguo: false,
          pregunta: null,
          missing_field: null
        },
        need_ai: false
      }
    }));
  }

  // Seguridad: no guardar parcialmente un lote. Si una línea no se entiende,
  // rechazamos el mensaje completo para que el usuario lo reenvíe corregido.
  return [{
    json: {
      _cfg: cfg,
      chat_id: chatId,
      telegram_user_id: userId,
      telegram_message_id: messageId,
      persona,
      text,
      pending_context: null,
      batch_error: true,
      batch_lines: batchLines,
      quick: { intent:'desconocido', confidence:0, ambiguo:true },
      need_ai: true
    }
  }];
}

const compactExpense = parseCompactExpense(text);
const rawAmount = compactExpense?.amount ?? extractAmount(text);
const detectedCurrency = compactExpense?.currency || 'ARS';
const detectedCot = compactExpense?.cot || null;
const amount = detectedCurrency === 'USD'
  ? (detectedCot ? rawAmount * detectedCot : null)
  : rawAmount;
const date = extractDate(text);
let quick = {
  intent: 'desconocido',
  clase: null,
  subtipo: null,
  monto_ars: amount,
  moneda_original: detectedCurrency,
  monto_original: rawAmount,
  cotizacion_ars: detectedCot,
  fuente_cotizacion: detectedCot ? 'OPERACIÓN REAL MANUAL' : null,
  cuenta_origen: null,
  cuenta_destino: null,
  categoria: null,
  detalle: text || null,
  fecha: date,
  inversion: null,
  concepto_vencimiento: null,
  frecuencia: null,
  query_type: null,
  query_category: null,
  query_categories: [],
  query_period: null,
  query_periods: [],
  query_month: null,
  query_year: null,
  query_days: null,
  query_only_cards: false,
  query_investment: null,
  confidence: 0.0,
  ambiguo: false,
  pregunta: null,
  missing_field: null
};


const queryStarter =
  /^(que|cual|cuales|cuanto|cuanta|cuantos|cuantas|cuando|donde|como|por que|porque|mostra|mostrame|mostrar|muestra|muestrame|lista|listame|listar|detalle|detallame|resumen|resumime|decime|dime|dame|quiero ver|quiero saber|necesito ver|ver)\b/.test(t);

const queryNounPhrase =
  /^(gastos|ingresos|vencimientos|deuda|disponible|patrimonio|inversiones|ahorro)\b/.test(t);

const queryColloquial =
  /\b(en que gaste|en que gastamos|en que se gasto|donde se fue la plata|donde fue la plata|cuanta plata hay|cuanta plata tenemos|cuanto debemos|que debemos|que hay que pagar|que tengo que pagar|que tenemos que pagar)\b/.test(t);

const isQueryText = text.startsWith('¿') || queryStarter || queryNounPhrase || queryColloquial;
const isCorrectionText = /\b(correg|modific|cambia|cambiar)\w*/.test(t);

function parseCorrectionCommand(original) {
  const raw = String(original ?? '').trim();

  // Formato determinístico:
  // corregir <movimiento a buscar> - monto <nuevo>
  // También acepta "|" y la palabra "por" como separadores.
  const m = raw.match(
    /^\s*(?:corregir|corregi|corrige|cambiar|cambia|modificar|modifica)\s+(.+?)(?:\s*\|\s*|\s+-\s+|\s+por\s+)(monto|importe|categoria|categoría|fecha|detalle)\s+(.+?)\s*$/i
  );
  if (!m) return null;

  const search = m[1].trim();
  const field = norm(m[2]);
  const value = m[3].trim();

  const out = {
    correction_search_text: search,
    correction_search_date: extractDate(search),
    correction_search_amount: extractAmount(search),
    correction_new_date: null,
    correction_new_amount: null,
    correction_new_category: null,
    correction_new_account_origin: null,
    correction_new_account_dest: null,
    correction_new_detail: null,
    correction_new_class: null,
    correction_new_subtype: null,
    correction_reason: raw
  };

  if (field === 'monto' || field === 'importe') {
    const n = parseMoney(value);
    if (n === null) return null;
    out.correction_new_amount = n;
  } else if (field === 'categoria') {
    const c = manualCategory(norm(value));
    if (!c) return null;
    out.correction_new_category = c;
  } else if (field === 'fecha') {
    const d = extractDate(value);
    if (!d) return null;
    out.correction_new_date = d;
  } else if (field === 'detalle') {
    if (!value) return null;
    out.correction_new_detail = value;
  }

  return out;
}

const correctionCmd = isCorrectionText ? parseCorrectionCommand(text) : null;

const isManualIncomeText =
  /\b(ingreso|ingresos|cobre|cobramos|cobro|sueldo|subsidio|subsidios)\b/.test(t) ||
  /^\s*ingreso\b/.test(t);

function manualIncomeCategory(s) {
  if(/\bsueldo titular_a\b/.test(s)) return 'Sueldo Titular A';
  if(/\bsueldo titular_b\b/.test(s)) return 'Sueldo Titular B';
  if(/\bsueldo\b/.test(s)) return persona==='Titular B' ? 'Sueldo Titular B' : 'Sueldo Titular A';
  if(/\bcositas de casa\b/.test(s)) return 'Cositas de Casa';
  if(/\bsubsidios?\b/.test(s)) return 'Subsidios';
  if(/\botros? ingresos?\b/.test(s)) return 'Otros ingresos';
  return null;
}

const incomeCategory = isManualIncomeText ? manualIncomeCategory(t) : null;
const isManualExpenseText = /\b(gaste|gastamos|gasto|pague|pagamos|compre|compramos|abone|abonamos)\b/.test(t);

function detectQueryCategories(s) {
  const rules = [
    [/\bcositas de casa\b/, 'Cositas de Casa'],
    [/\bgastos? financieros?\b/, 'Gastos financieros'],
    [/\bgastos? varios\b/, 'Gastos varios'],
    [/\bcomida\b|\balimentacion\b/, 'Comida'],
    [/\bsalud\b/, 'Salud'],
    [/\beducacion\b/, 'Educación'],
    [/\bocio\b/, 'Ocio'],
    [/\bimpuestos?\b/, 'Impuestos'],
    [/\bvehiculos?\b|\bsuran\b|\b(?:auto|ford|el|del)\s+fiesta\b|\bgastos?\s+(?:de\s+)?fiesta\b/, 'Vehículos']
  ];
  const found=[];
  for (const [rx,label] of rules) {
    const m=s.match(rx);
    if(m) found.push({label,pos:m.index??99999});
  }

  // "Casa" puede aparecer dentro de "Cositas de Casa"; no duplicarla por eso.
  const houseScan=s.replace(/cositas de casa/g,'cositas_hogar');
  const hm=houseScan.match(/\b(?:para|de)\s+la\s+casa\b|\bgastos?\s+(?:de\s+)?casa\b|\bcasa\b/);
  if(hm) found.push({label:'Casa',pos:hm.index??99999});

  found.sort((a,b)=>a.pos-b.pos);
  return [...new Set(found.map(x=>x.label))];
}
function detectQueryCategory(s) {
  return detectQueryCategories(s)[0] || null;
}

function detectQueryPeriods(s) {
  const monthMap={enero:1,febrero:2,marzo:3,abril:4,mayo:5,junio:6,julio:7,agosto:8,septiembre:9,setiembre:9,octubre:10,noviembre:11,diciembre:12};
  const years=[...s.matchAll(/\b(20\d{2})\b/g)].map(m=>Number(m[1]));
  const globalYear=years.length===1 ? years[0] : todayParts().y;
  const out=[];
  const rx=/\b(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+(?:de\s+)?(20\d{2}))?\b/g;
  let m;
  while((m=rx.exec(s))!==null){
    const month=monthMap[m[1]];
    const year=m[2]?Number(m[2]):globalYear;
    if(!out.some(z=>z.month===month && z.year===year)) out.push({period:'specific_month',month,year});
  }
  return out;
}

function detectQueryPeriod(s) {
  const many=detectQueryPeriods(s);
  if(many.length) return many[0];
  if(/\b(este mes|mes actual|mes en curso)\b/.test(s)) return {period:'current_month'};
  if(/\b(mes pasado|mes anterior|mes que paso)\b/.test(s)) return {period:'previous_month'};
  if(/\b(este ano|ano actual|ano en curso)\b/.test(s)) return {period:'current_year'};
  if(/\b(esta semana|semana actual|semana en curso)\b/.test(s)) return {period:'current_week'};

  const nd=s.match(/\b(?:proximos?|siguientes?)\s+(\d+)\s+dias\b/);
  if(nd) return {period:'next_days',days:Number(nd[1])};

  if(/\b(hasta\s+)?fin de mes\b/.test(s)) return {period:'until_month_end'};
  if(/\b(historico|historial completo|desde el inicio|desde que empezamos|todo el historial)\b/.test(s)) return {period:'all'};
  return {period:null};
}

function detectQueryInvestment(s) {
  if(/\bfima\b/.test(s) && !/\bbalanz\b/.test(s)) return 'FIMA';
  if(/\bbalanz\b/.test(s) && !/\bfima\b/.test(s)) return 'Balanz';
  return null;
}

function detectQueryType(s) {
  // Comparaciones y análisis primero, para que no caigan en reglas genéricas de gastos.
  if(/\b(mes|cual mes|que mes).*(mas gastos|mas gastamos|mayor gasto|gastamos mas)\b/.test(s) ||
     /\bmes con mas gastos\b/.test(s)) return 'mes_mas_gastos';

  if(/\b(compar|comparame|comparar)\w*.*\b(gastos?|mes)\b/.test(s) ||
     /\b(gaste|gastamos|gastos?).*(mas|menos).*(mes pasado|mes anterior)\b/.test(s) ||
     /\b(por que|porque).*(gaste|gastamos|gastos?).*(mas|menos)\b/.test(s) ||
     /\bque categoria.*(aumento|subio|crecio).*(mas)\b/.test(s)) return 'comparar_gastos_mes_anterior';

  if(/\b(por categoria|por categorias|por rubro|por rubros|distribucion de gastos|desglose de gastos|resumen de gastos)\b/.test(s) ||
     /\b(en que|donde).*(gaste|gastamos|se gasto|se fue).*(plata|dinero)?\b/.test(s) ||
     /\bcomo se repartieron los gastos\b/.test(s)) return 'gastos_por_categoria_periodo';

  // Detalle/listado de gastos: "qué gastos hubo", "mostrame los gastos", etc.
  if(/\b(que|cuales)\s+(gastos|compras)\b/.test(s) ||
     /\b(que|cuales)\s+(gastamos|pagamos|compramos)\b/.test(s) ||
     /\b(gastos|compras)\s+(hubo|hicimos|tuvimos|tenemos|realizamos)\b/.test(s) ||
     /\b(mostra|mostrame|mostrar|muestra|muestrame|lista|listame|listar|detalle|detallame|ver)\b.*\b(gastos|compras)\b/.test(s) ||
     /^gastos\b/.test(s) && !/\b(cuanto|total|suma|sumaron|monto|por categoria|por rubro)\b/.test(s)) {
    return 'detalle_gastos_periodo';
  }

  // Total de gastos.
  if(/\b(cuanto|cuanta|total|suma|sumaron|monto).*\b(gaste|gastamos|gasto|gastos|pagamos|pague|compras)\b/.test(s) ||
     /\b(gastos|compras).*\b(total|totales|sumaron|fueron|monto)\b/.test(s) ||
     /\bcuanto se gasto\b/.test(s)) return 'gastos_periodo';

  // Detalle/listado de ingresos.
  if(/\b(que|cuales)\s+(ingresos|cobros)\b/.test(s) ||
     /\b(ingresos|cobros)\s+(hubo|tuvimos|tenemos|entraron)\b/.test(s) ||
     /\b(mostra|mostrame|mostrar|muestra|muestrame|lista|listame|listar|detalle|detallame|ver)\b.*\b(ingresos|cobros)\b/.test(s) ||
     /^ingresos\b/.test(s) && !/\b(cuanto|total|suma|sumaron|monto)\b/.test(s)) {
    return 'detalle_ingresos_periodo';
  }

  // Total de ingresos.
  if(/\b(cuanto|cuanta|total|suma|sumaron|monto).*\b(ingreso|ingresos|entro|entraron|cobre|cobramos|cobros)\b/.test(s) ||
     /\b(ingresos|cobros).*\b(total|totales|sumaron|fueron|monto)\b/.test(s) ||
     /\bcuanto entro\b/.test(s)) return 'ingresos_periodo';

  // Disponible / liquidez.
  if(/\bdisponible\b/.test(s) ||
     /\bsaldo disponible\b/.test(s) ||
     /\b(cuanta|cuanto).*(plata|dinero|guita).*(hay|tenemos|queda|quedo)\b/.test(s) ||
     /\b(cuanta|cuanto).*(hay|tenemos|queda|quedo).*(plata|dinero|guita)\b/.test(s) ||
     /\b(que|cuanto).*(tenemos|hay).*(cuentas?)\b/.test(s)) return 'disponible_actual';

  // Invertido / saldos de FIMA o Balanz.
  if(/\b(invertid|inversion|inversiones)\w*\b/.test(s) && !/\b(gan|rind|rendimiento|resultado|rentabilidad)\w*\b/.test(s) ||
     /\b(fima|balanz)\b.*\b(saldo|cuanto tengo|cuanto hay|valor actual)\b/.test(s) ||
     /\b(saldo|cuanto tengo|cuanto hay|valor actual)\b.*\b(fima|balanz)\b/.test(s)) return 'invertido_actual';

  // Deuda de tarjetas.
  if(/\b(tarjeta|tarjetas)\b.*\b(debo|debemos|deuda|saldo pendiente|pendiente|cuanto pagar)\b/.test(s) ||
     /\b(debo|debemos|deuda|saldo pendiente|pendiente)\b.*\b(tarjeta|tarjetas)\b/.test(s)) return 'deuda_tarjetas';

  // Total de vencimientos.
  if(/\b(cuanto|total|suma|suman|sumaron|monto).*\b(venc|pagar|pagos pendientes)\w*\b/.test(s) ||
     /\b(vencimientos?|pagos pendientes).*\b(total|suma|suman|monto)\b/.test(s) ||
     /\bcuanto (tengo|tenemos) que pagar\b/.test(s) ||
     /\bcuanto hay que pagar\b/.test(s)) return 'total_vencimientos_periodo';

  // Listado de vencimientos.
  if(/\b(que|cuales).*\b(venc|vencimiento|pagar)\w*\b/.test(s) ||
     /\b(vencimientos?|pagos pendientes)\b/.test(s) ||
     /\b(mostra|mostrame|mostrar|muestra|muestrame|lista|listame|detalle|ver)\b.*\b(vencimientos?|pagos pendientes)\b/.test(s) ||
     /\bque hay que pagar\b/.test(s) ||
     /\bque (tengo|tenemos) que pagar\b/.test(s)) return 'vencimientos_periodo';

  // Rendimiento de inversiones.
  if(/\b(fima|balanz|inversion|inversiones)\b.*\b(gan|rindi|rindio|rindieron|resultado|rentabilidad|rendimiento)\w*\b/.test(s) ||
     /\b(gan|rindi|rindio|rindieron|resultado|rentabilidad|rendimiento)\w*\b.*\b(fima|balanz|inversion|inversiones)\b/.test(s) ||
     /\bcuanto gane con\b.*\b(fima|balanz|inversiones?)\b/.test(s)) return 'resultado_inversiones_periodo';

  // Ahorro / resultado familiar.
  if(/\b(ahorro|ahorramos|ahorre|resultado familiar|balance familiar)\b/.test(s) ||
     /\bcuanto nos quedo\b.*\b(mes|ano)\b/.test(s)) return 'ahorro_periodo';

  if(/\bpatrimonio\b/.test(s) ||
     /\bcuanto (tenemos|tengo) en total\b.*\b(activos|menos deudas)?\b/.test(s)) return 'patrimonio_actual';

  return null;
}

if (pending) {
  quick.intent = 'respuesta_pendiente';
  quick.confidence = 0;
} else if (!isQueryText && /\b(vencimiento|vence|vencen)\b/.test(t)) {
  quick.intent = 'vencimiento';
  quick.concepto_vencimiento = cleanConceptVencimiento(text);
  quick.confidence = (quick.fecha && quick.monto_ars && quick.concepto_vencimiento) ? 0.99 : 0.65;
  if (!quick.fecha) { quick.ambiguo = true; quick.missing_field='fecha'; quick.pregunta='¿Qué fecha vence?'; }
  else if (!quick.monto_ars) { quick.ambiguo = true; quick.missing_field='monto'; quick.pregunta='¿Cuál es el importe del vencimiento?'; }
  else if (!quick.concepto_vencimiento) { quick.ambiguo = true; quick.missing_field='concepto'; quick.pregunta='¿Qué concepto vence?'; }
} else if (!isQueryText && /\b(fima|balanz)\b/.test(t) && /\bsaldo\b/.test(t)) {
  quick.intent = 'saldo_inversion';
  quick.inversion = /\bfima\b/.test(t) ? 'FIMA' : 'Balanz';
  quick.confidence = (quick.fecha && quick.monto_ars) ? 0.99 : 0.70;
  if (!quick.fecha) { quick.ambiguo = true; quick.missing_field='fecha'; quick.pregunta=`¿De qué fecha es el saldo de ${quick.inversion}?`; }
  else if (!quick.monto_ars) { quick.ambiguo = true; quick.missing_field='monto'; quick.pregunta=`¿Cuál es el saldo de ${quick.inversion}?`; }
} else if (!isQueryText && !isCorrectionText && amount && isManualIncomeText && incomeCategory) {
  quick.intent = 'movimiento';
  quick.clase = 'Ingreso';
  quick.subtipo = 'Ingreso';
  // Regla operativa: todo ingreso cargado manualmente por Telegram entra en Efectivo.
  quick.cuenta_destino = 'Efectivo';
  quick.categoria = incomeCategory;
  quick.fecha = quick.fecha || iso(todayParts().y,todayParts().m,todayParts().d);
  quick.confidence = 0.99;
} else if (!isQueryText && !isCorrectionText && !isManualIncomeText && (compactExpense || rawAmount) && (isManualExpenseText || compactExpense)) {
  quick.intent = 'movimiento';
  quick.clase = 'Egreso';
  quick.subtipo = compactExpense?.currency === 'USD' ? 'Gasto en efectivo USD' : 'Compra';
  // ARS manual -> Efectivo. USD manual -> Efectivo USD.
  quick.cuenta_origen = compactExpense?.currency === 'USD' ? 'Efectivo USD' : 'Efectivo';
  quick.categoria = compactExpense?.category || manualCategory(t);
  quick.fecha = quick.fecha || iso(todayParts().y,todayParts().m,todayParts().d);
  quick.confidence = quick.categoria ? 0.99 : 0.78;
} else if (isQueryText) {
  quick.intent = 'consulta';

  quick.query_categories = detectQueryCategories(t);
  quick.query_category = quick.query_categories[0] || null;
  quick.query_investment = detectQueryInvestment(t);

  quick.query_periods = detectQueryPeriods(t);
  const qp = quick.query_periods[0] || detectQueryPeriod(t);
  quick.query_period = qp.period;
  quick.query_month = qp.month ?? null;
  quick.query_year = qp.year ?? null;
  quick.query_days = qp.days ?? null;

  quick.query_only_cards = /\b(tarjeta|tarjetas)\b/.test(t);
  quick.query_type = detectQueryType(t);

  // Períodos por defecto según el tipo de consulta.
  if (quick.query_type) {
    if (!quick.query_period) {
      if (['vencimientos_periodo'].includes(quick.query_type)) {
        quick.query_period = 'current_week';
      } else if (['total_vencimientos_periodo'].includes(quick.query_type)) {
        quick.query_period = 'until_month_end';
      } else if (['mes_mas_gastos','comparar_gastos_mes_anterior'].includes(quick.query_type)) {
        quick.query_period = quick.query_type === 'mes_mas_gastos' ? 'current_year' : 'current_month';
      } else if (['disponible_actual','invertido_actual','deuda_tarjetas','patrimonio_actual'].includes(quick.query_type)) {
        quick.query_period = null;
      } else {
        quick.query_period = 'current_month';
      }
    }
  }

  quick.confidence = quick.query_type ? 0.99 : 0.60;
} else if (isCorrectionText) {
  quick.intent = 'correccion';
  if (correctionCmd) {
    Object.assign(quick, correctionCmd);
    quick.confidence = 0.99;
    quick.ambiguo = false;
  } else {
    quick.confidence = 0.40;
    quick.ambiguo = true;
  }
}

// Las consultas que piden explicación, causas, interpretación o tendencias
// se derivan a IA aunque el parser determinístico reconozca período/categoría.
// El determinístico sigue resolviendo totales, listados y comparaciones simples.
const isReasoningQuery = quick.intent === 'consulta' && (
  /\bpor que\b/.test(t) ||
  /\ba que se debe\b/.test(t) ||
  /\bque explica\b/.test(t) ||
  /\bexplica(?:me)?\b/.test(t) ||
  /\b(?:analiza|analizame|analizar|interpretar|interpreta|interpretame)\b/.test(t) ||
  /\b(?:tendencia|tendencias|evolucion|mejorando|empeorando)\b/.test(t) ||
  /\bcomo venimos\b/.test(t) ||
  /\bque conclusion\b/.test(t)
);

const needAI = !!pending || isReasoningQuery || quick.intent === 'desconocido' ||
  (quick.intent === 'movimiento' && !quick.categoria) ||
  (quick.intent === 'correccion' && !correctionCmd) ||
  (quick.intent === 'consulta' && !quick.query_type);

return [{
  json: {
    _cfg: cfg,
    chat_id: chatId,
    telegram_user_id: userId,
    telegram_message_id: messageId,
    persona,
    text,
    pending_context: pending,
    quick,
    need_ai: needAI
  }
}];

const trig=$('Entrada desde 01').first().json;
const cfg=$('CONFIGURACIÓN - EDITAR').first().json._cfg;
const chatId=String(trig.message?.chat?.id??'');
const raw=String(trig.message?.text??trig.message?.caption??'').trim();
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
const rows=$('Leer pendientes del chat').all().map(i=>i.json);
const active=rows.some(row=>String(row['Chat ID']??'')===chatId && String(row.Estado||'').toUpperCase()==='PENDIENTE' && String(row['Intención']||'').toUpperCase()==='CIERRE_MENSUAL');
const t=norm(raw);
const explicit=/\b(cerrar|cierre|continuar cierre|estado cierre|faltantes cierre|que falta del cierre|confirmar cierre|cancelar cierre)\b/.test(t);
return [{json:{...trig,_cfg:cfg,chat_id:trig.message?.chat?.id,user_id:trig.message?.from?.id,text:raw,is_close_event:active||explicit}}];
